for(int trial=1;trial<=5;trial++){ck(cudaMemset(do_,165,out.size()));ck(cudaDeviceSynchronize());auto a=std::chrono::steady_clock::now();for(int k=0;k<R;k++)run();ck(cudaDeviceSynchronize());double secs=std::chrono::duration<double>(std::chrono::steady_clock::now()-a).count()/R;ck(cudaMemcpy(out.data(),do_,out.size(),cudaMemcpyDeviceToHost));ck(cudaMemcpy(s.data(),ds,s.size(),cudaMemcpyDeviceToHost));ck(cudaMemcpy(b.data(),db,b.size()*2,cudaMemcpyDeviceToHost));ck(cudaMemcpy(sc.data(),dc,8,cudaMemcpyDeviceToHost));bool ok=std::equal(expected.begin(),expected.end(),out.begin()+64)&&std::equal(in.begin(),in.end(),s.begin()+64)&&std::equal(bias.begin(),bias.end(),b.begin()+32);int err=0;double mr=0;for(size_t j=0;j<N;j++){int e=abs(int(out[j+64])-int(expected[j]));err=std::max(err,e);mr=std::max(mr,double(e)/std::max(double(expected[j]),1e-300));}result.assign(s.begin()+64,s.end()-64);auto append=[&](const void*p,size_t n){auto q=(const uint8_t*)p;result.insert(result.end(),q,q+n);};append(b.data()+32,B*2);append(sc.data(),8);int32_t params[]={m,h,d,R};append(params,16);append(out.data()+64,N);append(out.data(),64);append(out.data()+N+64,64);append(s.data(),64);append(s.data()+N+64,64);append(b.data(),64);append(b.data()+B+32,64);for(size_t j=result.size()-384;j<result.size();j++)ok&=result[j]==(j<result.size()-256?165:90);all&=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)result.data(),result.size());f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":%.12g,\"error_metric_domain\":\"exact_FP8bytes_BF16intermediates_transpose_and_guardbytes_not_attentionquality\",\"jit_excluded\":true,\"internal_repeats\":%d,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint8\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,secs,ok?"true":"false",N+384,err,mr,R,path.c_str(),result.size());}cudaFree(ds);cudaFree(do_);cudaFree(db);cudaFree(dc);printf("%s\n",all?"PASS":"FAIL");return all?0:1;}
